package com.allinone.supply.controller;
import com.allinone.common.core.controller.BaseController; import com.allinone.common.core.page.TableDataInfo; import com.allinone.common.utils.poi.ExcelUtil; import com.allinone.supply.domain.LedgerExportRow; import com.allinone.supply.domain.LedgerRow; import com.allinone.supply.service.ILedgerService; import jakarta.servlet.http.HttpServletResponse; import java.util.List; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/supply/ledger") public class LedgerController extends BaseController { @Autowired private ILedgerService service; @PreAuthorize("@ss.hasPermi('supply:ledger:list')") @GetMapping("/combined") public TableDataInfo combined(@RequestParam(required=false) String number,@RequestParam(required=false) String supplierName,@RequestParam(required=false) String approvalStatus){startPage();List<LedgerRow> list=service.combined(number,supplierName,approvalStatus);return getDataTable(list);} @PreAuthorize("@ss.hasPermi('supply:ledger:export')") @PostMapping("/export") public void export(HttpServletResponse response,@RequestParam(required=false) String number,@RequestParam(required=false) String supplierName,@RequestParam(required=false) String approvalStatus){List<LedgerExportRow> list=service.combined(number,supplierName,approvalStatus).stream().map(LedgerExportRow::new).toList();new ExcelUtil<>(LedgerExportRow.class).exportExcel(response,list,"供应链综合台账");} }
